    try:
        return decoder.decode(content)
    except JSONDecodeError as exc:
        position = Position(column_no=exc.colno, line_no=exc.lineno, char_index=exc.pos)
        raise ParseError(text=exc.msg + '.', code='parse_error', position=position)
