import pytest

from typesystem.exceptions import ValidationError
from typesystem.fields import Integer, String
from typesystem.schemas import Schema
from typesystem.tokenize.tokenize_json import validate_json


def _texts(messages):
    return [
        str(getattr(message, "text", message)).lower() for message in messages
    ]


def _validation_messages(exc):
    messages = getattr(exc, "messages", None)
    if callable(messages):
        return messages()
    if messages is not None:
        return list(messages)
    return [str(exc)]


def test_validate_json_valid_field_str_content():
    value = validate_json("123", validator=Integer())

    assert value == 123


def test_validate_json_valid_field_bytes_content():
    value = validate_json(b'"hello"', validator=String())

    assert value == "hello"


def test_validate_json_valid_schema():
    class Person(Schema):
        name = String(max_length=100)
        age = Integer()

    value = validate_json('{"name": "Tom", "age": 30}', validator=Person)

    if isinstance(value, dict):
        assert value == {"name": "Tom", "age": 30}
    else:
        assert value.name == "Tom"
        assert value.age == 30


def test_validate_json_field_validation_error():
    with pytest.raises(ValidationError) as excinfo:
        validate_json('"hello"', validator=Integer())

    messages = _validation_messages(excinfo.value)
    assert messages
    assert any("integer" in text for text in _texts(messages))


def test_validate_json_schema_validation_error():
    class Person(Schema):
        name = String(max_length=100)
        age = Integer()

    with pytest.raises(ValidationError) as excinfo:
        validate_json('{"name": "Tom"}', validator=Person)

    messages = _validation_messages(excinfo.value)
    assert messages
    assert any("required" in text for text in _texts(messages))


def test_validate_json_invalid_json():
    from typesystem.exceptions import ParseError

    with pytest.raises(ParseError) as excinfo:
        validate_json("{", validator=Integer())

    assert str(excinfo.value)
